component.script:
"""Data Adapter: translate request_data between two components by a mapping table.

The table is node configuration, so the outgoing key set is decided per node,
not by this script. With no table the inbound data is forwarded unchanged,
which keeps an unconfigured node harmless. A malformed table raises ValueError
naming the bad entry, and a value that cannot be cast raises naming the field:
the adapter never forwards data it silently got wrong.
"""

import json

import perceivo

_TRANSFORMS = ("direct", "rename", "type_cast", "extract", "constant")
# The platform's scalar property types. "number" is deliberately absent: it was
# removed as a property type platform-wide.
_CASTS = ("string", "integer", "float", "boolean")
_TRUE = ("true", "1", "yes", "y", "on")
_FALSE = ("false", "0", "no", "n", "off", "")
_ABSENT = object()


def _cast(value, cast_to: str, where: str):
    """Coerce a value to one of the scalar property types; null stays null."""
    if value is None:
        return None
    if cast_to == "string":
        if isinstance(value, bool):
            return "true" if value else "false"
        if isinstance(value, (dict, list)):
            return json.dumps(value)
        return str(value)
    if cast_to == "boolean":
        if isinstance(value, bool):
            return value
        text = str(value).strip().lower()
        if text not in _TRUE and text not in _FALSE:
            raise ValueError(
                f"{where}: {value!r} is not a boolean (true/false, yes/no, 1/0, on/off)."
            )
        return text in _TRUE
    if isinstance(value, (bool, dict, list)):
        raise ValueError(f"{where}: {value!r} cannot be cast to {cast_to}.")
    if cast_to == "integer" and isinstance(value, int):
        return value
    text = str(value).strip()
    if cast_to == "integer":
        try:
            return int(text)  # exact, however many digits
        except ValueError:
            pass
    try:
        number = float(text)
    except ValueError:
        raise ValueError(f"{where}: {value!r} is not a number.") from None
    if cast_to == "float":
        return number
    if not number.is_integer():
        raise ValueError(f"{where}: {value!r} is not a whole number.")
    return int(number)


def _extract(data, dotted_path: str):
    """Resolve a dotted path against nested dicts; null when any step is missing."""
    current = data
    for part in dotted_path.split("."):
        if not isinstance(current, dict):
            return None
        current = current.get(part)
    return current


def _load_mappings(raw) -> list:
    """Parse and check the mapping table, or raise naming what is wrong with it."""
    if raw is None or (isinstance(raw, str) and not raw.strip()):
        return []
    if isinstance(raw, str):
        try:
            raw = json.loads(raw)
        except json.JSONDecodeError as exc:
            raise ValueError(
                f"Request Mappings is not valid JSON: {exc.msg} (line {exc.lineno})."
            ) from None
    if not isinstance(raw, list):
        raise ValueError("Request Mappings must be a JSON array of mapping objects.")

    mappings = []
    for number, entry in enumerate(raw, start=1):
        where = f"Request Mappings entry {number}"
        if not isinstance(entry, dict):
            raise ValueError(f"{where} is not an object.")
        target = str(entry.get("target_field") or "").strip()
        if not target:
            raise ValueError(f"{where} has no target_field.")
        transform = str(entry.get("transform") or "direct").strip().lower()
        if transform not in _TRANSFORMS:
            raise ValueError(
                f"{where}: transform is {transform!r}. Choose one of: {', '.join(_TRANSFORMS)}."
            )
        source = str(entry.get("source_field") or "").strip()
        if transform != "constant" and not source:
            raise ValueError(f"{where}: the {transform} transform needs a source_field.")
        if transform == "constant" and "value" not in entry:
            raise ValueError(f"{where}: the constant transform needs a value.")
        cast_to = str(entry.get("cast_to") or "").strip().lower()
        if transform == "type_cast" and not cast_to:
            raise ValueError(f"{where}: the type_cast transform needs cast_to.")
        if cast_to and cast_to not in _CASTS:
            raise ValueError(
                f"{where}: cast_to is {cast_to!r}. Choose one of: {', '.join(_CASTS)}."
            )
        mappings.append(
            {
                "where": f"{where} ({target})",
                "target": target,
                "transform": transform,
                "source": source,
                "cast_to": cast_to,
                "value": entry.get("value"),
            }
        )
    return mappings


def _resolve(data: dict, mapping: dict):
    """One mapping's value, or _ABSENT when its source field did not arrive.

    An extract whose nested path misses is null, a real value the target
    carries; a direct, rename or type_cast whose source did not arrive
    contributes nothing.
    """
    transform, source = mapping["transform"], mapping["source"]
    if transform == "constant":
        value = mapping["value"]
    elif transform == "extract":
        value = _extract(data, source)
    elif source in data:
        value = data[source]
    else:
        return _ABSENT
    if mapping["cast_to"]:
        value = _cast(value, mapping["cast_to"], mapping["where"])
    return value


@perceivo.adapter
async def data_adapter(
    input: perceivo.primitives.AdapterInput,
) -> perceivo.primitives.AdapterOutput:
    """Reshape request_data with the configured mapping table.

    The output holds exactly the table's target fields, in table order (a later
    entry for the same target wins). With no table the inbound data is
    forwarded unchanged. The artifact is forwarded untouched and never
    dereferenced, so it is welcome but never required.
    """
    incoming = input.request_data or {}
    if not isinstance(incoming, dict):
        incoming = {"data": incoming}

    mappings = _load_mappings(perceivo.params.get("request_mappings", "[]"))
    if not mappings:
        perceivo.log.info(
            f"Data Adapter: no mappings configured; forwarding {len(incoming)} field(s) unchanged."
        )
        return perceivo.primitives.AdapterOutput(
            artifact=input.artifact, response_data=dict(incoming)
        )

    outgoing, missing = {}, []
    for mapping in mappings:
        value = _resolve(incoming, mapping)
        if value is _ABSENT:
            missing.append(mapping["source"])
        else:
            outgoing[mapping["target"]] = value
    if missing:
        perceivo.log.warning(
            f"Data Adapter: {len(missing)} source field(s) did not arrive and were left out.",
            missing=missing,
        )
    perceivo.log.info(
        f"Data Adapter: mapped {len(incoming)} inbound field(s) to {len(outgoing)} outbound "
        f"field(s) via {len(mappings)} mapping(s)."
    )
    return perceivo.primitives.AdapterOutput(artifact=input.artifact, response_data=outgoing)
